"faq-q1":"I-Pi Network imahhala ukungena?","faq-a1":"Yebo — imahhala ngokuphelele. Sebenzisa ikhodi yokuxhumana chigalex1 ku minepi.com/chigalex1.",
"faq-q2":"Ngidinga ukugcina i-app ivulekile ukumba?","faq-a2":"Cha. Thepha inkinobho yezulu kanye njalo emahora angama-24. Yilokho kuphela.",
"faq-q3":"Yini i-GCV futhi ibiluleke kanjani?","faq-a3":"I-GCV (Global Consensus Value) = $314,159 nge-1π sekubhaliwe ku-Pi blockchain.",
"faq-q4":"Ngithola ini nge-0.01π yobulungu?","faq-a4":"Ukufinyelela kwempilo yonke kwa: AI Chatbot, Uqeqesho lweKYC/KYB/Ukubhalisa/Ukuphepha, Ibalazwe le-Pi, Uhlu Lwabathengisi.",
