"pilaunch-big-sf2-title":"Ditsietso tsa Launchpad",
"pilaunch-big-sf2-body":"Fumana ka tlhamalalo ka Pi Browser.",
"pilaunch-big-sf3-title":"Ga go Ditefo tsa Pele",
"pilaunch-big-sf3-body":"O se ke wa romela Pi go motho.",
