"pilaunch-big-sf6-body":"Tlhokomologa melaetsa e e sa kopiwang.",
"pilaunch-big-faq-label":"❓ Dipotso",
"pilaunch-big-faq1-q":"A e teng jaanong?",
"pilaunch-big-faq1-a":"Ee, mo Testnet go tswa Mopitlwe 2026.",
