"pilaunch-big-faq2-a":"Ee, e a tlhokega.",
"pilaunch-big-faq3-q":"Pharologanyo mo gare ga go baya le go ikopanya?",
"pilaunch-big-faq3-a":"Go baya = go tshola. Go ikopanya = go romela.",
"pilaunch-big-faq4-q":"A batlhami ba Afrika ba ka tlhagisa merero?",
