  "pidex-safety-body":"Injira PiDEX binyuze muri Pi Browser gusa. Ntukoreshe imbuga z'inyuma. Ntugabanye ijambo ryawe ry'ibanga. Kora ubucuruzi bwa tokens zirebwa na Pi ecosystem gusa.",
