"lbl-faq":"Su'aalaha","sec-faq-title":"Su'aalaha Inta Badan La Weydiiyo",
"faq-q1":"Ma bilaash baa Pi Network ku biiri karaa?","faq-a1":"Haa — bilaash buuxa. Isticmaal koodhka referral chigalex1 ku minepi.com/chigalex1.",
