"faq-q4":"Maxaan ka helayaa xubnanimada 0.01π?","faq-a4":"Helitaan nolosha oo dhan oo: AI Chatbot, Tababarka KYC/KYB, Khariidadda Pi, Liiska Ganacsatada.",
"footer-tagline":"🌍 Africa Pi Network Education Hub",
